using CsvHelper; using System.Globalization; using System.Text;  namespace BinanceDataCollector.MarketScreenService;  // Используем тот же record, что и в MarketScreener // public record InterestingPair(string Symbol, decimal QuoteVolume, decimal PriceChangePercent);  public class DataExporter {     /// <summary>     /// Выводит отформатированный список пар в консоль.     /// </summary>     /// <param name="pairs">Список пар для вывода.</param>     public void PrintToConsole(IEnumerable<InterestingPair> pairs)     {         Console.WriteLine("\n--- ТОП Активных Пар (Консольный вывод) ---");          // Печатаем заголовок таблицы с выравниванием         Console.WriteLine($"{"#",-4}{"Символ",-12} | {"Объем (млн $)",-20} | {"Изменение % (24ч)",-20}");         Console.WriteLine(new string('-', 60)); // Разделительная линия          int rank = 1;         foreach (var pair in pairs)         {             // Форматируем каждую строку для аккуратного вывода             Console.WriteLine(                 $"{rank++,-4}" +                 $"{pair.Symbol,-12} | " +                 $"{pair.QuoteVolume / 1_000_000,-19:N2} | " +                 $"{pair.PriceChangePercent,-19:N2}"             );         }         Console.WriteLine(new string('-', 60));     }      /// <summary>     /// Сохраняет список пар в CSV-файл.     /// </summary>     /// <param name="pairs">Список пар для сохранения.</param>     /// <param name="filePath">Путь к файлу для сохранения.</param>     public async Task SaveToCsvAsync(IEnumerable<InterestingPair> pairs, string filePath)     {         try         {             // Используем await using для асинхронного освобождения ресурсов             await using var writer = new StreamWriter(filePath, false, Encoding.UTF8); // false - перезаписывать файл             await using var csv = new CsvWriter(writer, CultureInfo.InvariantCulture);              // CsvHelper автоматически создаст заголовки на основе имен свойств record'а             // (Symbol, QuoteVolume, PriceChangePercent)             await csv.WriteRecordsAsync(pairs);              Console.WriteLine($"\n[Успех] Данные успешно сохранены в файл: {Path.GetFullPath(filePath)}");         }         catch (Exception ex)         {             Console.WriteLine($"\n[Ошибка] Не удалось сохранить файл: {ex.Message}");         }     } } 